mapper.select:
SELECT bar.billExceptionHandleRecordId, DATE_FORMAT(bar.crt_time,'%Y-%m-%d') as revokeDate, bar.orderDate, bar.actualAmount, bar.receivedAmount, bar.chargeDate, bar.billNum, bar.patientId, bar.regDentistId, bar.revokeOperatorId, bar.revokeOperatorName FROM ( SELECT behr.id AS billExceptionHandleRecordId, bpr.orgId, behr.crt_time, bpr.orderDate AS orderDate, bpr.actualAmount, bpr.receivedAmount, bpr.chargeDate, bpr.billNum, bpr.patientId patientId, tr.dentist_id AS regDentistId, behr.crt_id AS revokeOperatorId, behr.crt_name AS revokeOperatorName FROM ( SELECT id, treatment_record_id, handled_record_id, crt_id, crt_name, crt_time FROM bill_exception_handle_record WHERE operate_type = 1 ) behr LEFT JOIN ( SELECT bpr.id, bpr.org_id AS orgId, bpr.patient_id AS patientId, bpr.received_amount AS receivedAmount, br.actual_receivable_amount AS actualAmount, br.bill_number AS billNum, DATE_FORMAT( bpr.crt_time, '%Y-%m-%d' ) AS chargeDate, DATE_FORMAT( ord.crt_time, '%Y-%m-%d' ) AS orderDate FROM bill_pay_record bpr LEFT JOIN bill_record br ON bpr.bill_record_id = br.id LEFT JOIN order_record ord ON bpr.order_record_id = ord.id ) bpr ON behr.handled_record_id = bpr.id LEFT JOIN treatment_record tr ON behr.treatment_record_id = tr.id ) bar
and bar.orgId = #{query.orgId}
and bar.billNum like concat('%', #{query.billNum}, '%')
and DATE_FORMAT(bar.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.revokeStartDate},'%Y-%m-%d')
and DATE_FORMAT(bar.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.revokeEndDate},'%Y-%m-%d')
and bar.chargeDate >= #{query.chargeStartDate}
and bar.chargeDate <= #{query.chargeEndDate}
and bar.regDentistId in
#{item}
ORDER BY bar.crt_time DESC

SELECT bar.billExceptionHandleRecordId, DATE_FORMAT(bar.crt_time,'%Y-%m-%d') as adjustDate, bar.orderDate, bar.actualAmount, bar.receivedAmount, bar.chargeDate, bar.billNum, bar.patientId, bar.regDentistId, bar.adjustOperatorId, bar.adjustOperatorName FROM ( SELECT behr.id AS billExceptionHandleRecordId, behr.org_id AS orgId, behr.crt_time, bpr.orderDate AS orderDate, bpr.actualAmount, bpr.receivedAmount, bpr.chargeDate, bpr.billNum, bpr.patientId patientId, tr.dentist_id AS regDentistId, behr.crt_id AS adjustOperatorId, behr.crt_name AS adjustOperatorName FROM ( SELECT id, org_id, treatment_record_id, handled_record_id, crt_id, crt_name, crt_time FROM bill_exception_handle_record WHERE operate_type = 0 ) behr LEFT JOIN ( SELECT bpr.id, bpr.patient_id AS patientId, bpr.received_amount AS receivedAmount, br.actual_receivable_amount AS actualAmount, br.bill_number AS billNum, DATE_FORMAT( bpr.crt_time, '%Y-%m-%d' ) AS chargeDate, DATE_FORMAT( ord.crt_time, '%Y-%m-%d' ) AS orderDate FROM bill_pay_record bpr LEFT JOIN bill_record br ON bpr.bill_record_id = br.id LEFT JOIN order_record ord ON bpr.order_record_id = ord.id ) bpr ON behr.handled_record_id = bpr.id LEFT JOIN treatment_record tr ON behr.treatment_record_id = tr.id ) bar
and bar.orgId = #{query.orgId}
and bar.billNum like concat('%', #{query.billNum}, '%')
and DATE_FORMAT(bar.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.adjustStartDate},'%Y-%m-%d')
and DATE_FORMAT(bar.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.adjustEndDate},'%Y-%m-%d')
and bar.chargeDate >= #{query.chargeStartDate}
and bar.chargeDate <= #{query.chargeEndDate}
and bar.regDentistId in
#{item}
ORDER BY bar.crt_time DESC

SELECT behr.id, behdr.orgId, DATE_FORMAT( behr.crt_time, '%Y-%m-%d' ) AS adjustDate, behdr.id AS billId, behdr.billDate, behdr.billNumber AS billNum, behdr.beforeAdjustDebtAmount, behdr.patientId patientId, tr.dentist_id AS regDentistId, behr.crt_id AS operatorId, behr.crt_name AS operatorName FROM ( SELECT id, org_id, treatment_record_id, crt_id, crt_name, crt_time FROM bill_exception_handle_record WHERE operate_type = 2 ) behr LEFT JOIN ( SELECT behdr.bill_handle_record_id, br.id, br.patient_id AS patientId, br.org_id AS orgId, br.bill_number AS billNumber, br.debt_amount AS beforeAdjustDebtAmount, DATE_FORMAT( br.crt_time, '%Y-%m-%d' ) AS billDate FROM bill_exception_handle_detail_record behdr LEFT JOIN bill_record br ON behdr.associate_record_id = br.order_record_id ) behdr ON behr.id = behdr.bill_handle_record_id LEFT JOIN treatment_record tr ON behr.treatment_record_id = tr.id
AND behr.org_id = #{query.orgId}
AND DATE_FORMAT(BEHR.crt_time, '%Y-%m') = #{query.currentMonth}
ORDER BY behr.id

SELECT bar.billExceptionHandleRecordId, bar.revokeDate, bar.billId, bar.billDate, bar.actualAmount, bar.receivedAmount, bar.chargeDate, bar.billNum, bar.patientId, bar.regDentistId, bar.revokeOperatorId, bar.revokeOperatorName FROM ( SELECT behr.id AS billExceptionHandleRecordId, bpr.orgId, DATE_FORMAT( behr.crt_time, '%Y-%m-%d' ) revokeDate, bpr.billId, bpr.billDate, bpr.actualAmount, bpr.receivedAmount, bpr.chargeDate, bpr.billNum, bpr.patientId patientId, tr.dentist_id AS regDentistId, behr.crt_id AS revokeOperatorId, behr.crt_name AS revokeOperatorName FROM ( SELECT id, treatment_record_id, handled_record_id, crt_id, crt_name, crt_time FROM bill_exception_handle_record WHERE operate_type = 1 ) behr LEFT JOIN ( SELECT bpr.id, bpr.org_id AS orgId, bpr.patient_id AS patientId, bpr.received_amount AS receivedAmount, br.id AS billId, br.actual_receivable_amount AS actualAmount, br.bill_number AS billNum, DATE_FORMAT( bpr.crt_time, '%Y-%m-%d' ) AS chargeDate, DATE_FORMAT( br.crt_time, '%Y-%m-%d' ) AS billDate FROM bill_pay_record bpr LEFT JOIN bill_record br ON bpr.bill_record_id = br.id ) bpr ON behr.handled_record_id = bpr.id LEFT JOIN treatment_record tr ON behr.treatment_record_id = tr.id ) bar
and bar.orgId = #{query.orgId}
and DATE_FORMAT(bar.revokeDate, '%Y-%m') = #{query.currentMonth}

SELECT billExceptionHandleRecordId, treatmentRecordId, billRefundRecordId, refundDate, refundAmount, billRecordId, billDate, billNum, patientId, actualAmount, receivedAmount, regDentistId, refundOperatorId, refundOperatorName, refundReason FROM ( SELECT behr.billExceptionHandleRecordId, behr.treatmentRecordId, behr.billRefundRecordId, DATE_FORMAT(brr.crt_time, '%Y-%m-%d') AS refundDate, brr.total_refund_amount AS refundAmount, behr.billRecordId, behr.billDate, behr.billNum, behr.patientId, behr.actualAmount, behr.receivedAmount, tr.dentist_id AS regDentistId, brr.crt_id AS refundOperatorId, brr.crt_name AS refundOperatorName, brr.reason AS refundReason FROM ( SELECT behr.billExceptionHandleRecordId, behr.treatmentRecordId, behr.billRecordId, behdr.associate_record_id AS billRefundRecordId, DATE_FORMAT(br.crt_time, '%Y-%m-%d') AS billDate, br.bill_number AS billNum, behr.patientId, br.actual_receivable_amount AS actualAmount, br.received_amount AS receivedAmount FROM ( SELECT behr.id AS billExceptionHandleRecordId, behr.handled_record_id AS billRecordId, behr.treatment_record_id AS treatmentRecordId, behr.patient_id AS patientId FROM bill_exception_handle_record behr
AND behr.operate_type = 3
AND behr.org_id = #{query.orgId}
AND DATE_FORMAT( behr.crt_time, '%Y-%m-%d' ) >= #{query.refundStartDate}
AND DATE_FORMAT( behr.crt_time, '%Y-%m-%d' ) <= #{query.refundEndDate}
) behr LEFT JOIN bill_exception_handle_detail_record behdr ON behr.billExceptionHandleRecordId = behdr.bill_handle_record_id LEFT JOIN bill_record br ON behr.billRecordId = br.id ) behr LEFT JOIN treatment_record tr ON behr.treatmentRecordId = tr.id LEFT JOIN bill_refund_record brr ON behr.billRefundRecordId = brr.id ) behr
AND behr.billNum like concat('%', #{query.billNum} , '%')
AND behr.billDate >= #{query.billStartDate}
AND behr.billDate <= #{query.billEndDate}
AND behr.regDentistId IN
#{item}
ORDER BY behr.billRefundRecordId DESC

select br.id as billId, date_format(br.crt_time, '%Y-%m-%d') as billDate, br.bill_number as billNum, br.patient_id as patientId, tr.dentist_id as regDentistId, br.receivable_amount as totalOriginalAmount, if(date_format(br.privilege_date, '%Y-%m-%d') > #{query.queryDate}, br.receivable_amount, br.actual_receivable_amount) as totalActualAmount, br.received_amount as receivedAmount from ( select behr.handled_record_id as treatmentId, behdr.associate_record_id as orderRecordId from bill_exception_handle_record behr left join bill_exception_handle_detail_record behdr on behr.id = behdr.bill_handle_record_id
and behr.operate_type = 2
and date_format(behr.crt_time, '%Y-%m-%d') > #{query.queryDate}
) behr left join bill_record br on br.order_record_id = behr.orderRecordId left join treatment_record tr on tr.id = behr.treatmentId
and br.debt_amount > 0
and br.org_id = #{query.orgId}
and tr.dentist_id in
#{item}
